1	import errors from '@tryghost/errors';
2	import tpl from '@tryghost/tpl';
3	import type {DatabaseSync} from 'node:sqlite';
4	import type {
5	    Automation,
6	    AutomationAction,
7	    AutomationEdge,
8	    AutomationSummary,
9	    AutomationsRepository,
10	    Page
11	} from './automations-repository';
12	
13	const messages = {
14	    invalidAutomationActionRevision: 'Automation action "{actionId}" of type "{actionType}" is missing required revision field "{field}".'
15	};
16	
17	interface AutomationRow {
18	    id: string;
19	    slug: string;
20	    name: string;
21	    status: string;
22	    created_at: string;
23	    updated_at: string;
24	}
25	
26	interface ActionRow {
27	    id: string;
28	    type: 'wait' | 'send_email';
29	    wait_hours: number | null;
30	    email_subject: string | null;
31	    email_lexical: string | null;
32	    email_sender_name: string | null;
33	    email_sender_email: string | null;
34	    email_sender_reply_to: string | null;
35	    email_design_setting_id: string | null;
36	}
37	
38	interface EdgeRow {
39	    source_action_id: string;
40	    target_action_id: string;
41	}
42	
43	export function createFakeDatabaseAutomationsRepository({
44	    getDatabase
45	}: {
46	    getDatabase: () => DatabaseSync;
47	}): AutomationsRepository {
48	    return {
49	        async browse(): Promise<Page<AutomationSummary>> {
50	            const database = getDatabase();
51	
52	            return withTransaction(database, () => {
53	                const rows = loadAutomations(database).map(row => buildAutomationSummary(row));
54	
55	                return {
56	                    data: rows,
57	                    meta: {
58	                        pagination: buildPagination(rows.length)
59	                    }
60	                };
61	            });
62	        },
63	
64	        async getById(id: string): Promise<Automation | null> {
65	            const database = getDatabase();
66	            return withTransaction(database, () => {
67	                const automation = loadAutomation(database, id);
68	
69	                if (!automation) {
70	                    return null;
71	                }
72	
73	                return buildAutomation(database, automation);
74	            });
75	        }
76	    };
77	}
78	
79	function withTransaction<T>(database: DatabaseSync, operation: () => T): T {
80	    database.exec('BEGIN TRANSACTION');
81	
82	    try {
83	        const result = operation();
84	        database.exec('COMMIT');
85	        return result;
86	    } catch (error) {
87	        database.exec('ROLLBACK');
88	        throw error;
89	    }
90	}
91	
92	function loadAutomation(database: DatabaseSync, automationId: string): AutomationRow | null {
93	    const automation = database.prepare(`
94	        SELECT id, slug, name, status, created_at, updated_at
95	        FROM automations
96	        WHERE id = ?
97	    `).get(automationId) as AutomationRow | undefined;
98	
99	    return automation ?? null;
100	}
101	
102	function loadAutomations(database: DatabaseSync): AutomationRow[] {
103	    return database.prepare(`
104	        SELECT id, slug, name, status, created_at, updated_at
105	        FROM automations
106	        ORDER BY created_at, id
107	    `).all() as unknown as AutomationRow[];
108	}
109	
110	function buildAutomation(database: DatabaseSync, automation: AutomationRow): Automation {
111	    return {
112	        ...buildAutomationSummary(automation),
113	        actions: loadActionRows(database, automation.id).map(row => buildActionPayload(row)),
114	        edges: loadEdgeRows(database, automation.id).map(row => buildEdgePayload(row))
115	    };
116	}
117	
118	function buildAutomationSummary(automation: AutomationRow): AutomationSummary {
119	    return {
120	        id: automation.id,
121	        slug: automation.slug,
122	        name: automation.name,
123	        status: automation.status,
124	        created_at: serializeDate(automation.created_at),
125	        updated_at: serializeDate(automation.updated_at)
126	    };
127	}
128	
129	function serializeDate(date: string) {
130	    const normalizedDate = new Date(date);
131	    normalizedDate.setMilliseconds(0);
132	    return normalizedDate.toISOString();
133	}
134	
135	function loadActionRows(database: DatabaseSync, automationId: string): ActionRow[] {
136	    return database.prepare(`
137	        SELECT
138	            a.id AS id,
139	            a.type AS type,
140	            r.wait_hours AS wait_hours,
141	            r.email_subject AS email_subject,
142	            r.email_lexical AS email_lexical,
143	            r.email_sender_name AS email_sender_name,
144	            r.email_sender_email AS email_sender_email,
145	            r.email_sender_reply_to AS email_sender_reply_to,
146	            r.email_design_setting_id AS email_design_setting_id
147	        FROM automation_actions a
148	        INNER JOIN automation_action_revisions r ON r.action_id = a.id
149	        WHERE a.automation_id = ?
150	            AND a.deleted_at IS NULL
151	            AND r.created_at = (
152	                SELECT MAX(created_at)
153	                FROM automation_action_revisions
154	                WHERE action_id = a.id
155	            )
156	        ORDER BY a.created_at, a.id
157	    `).all(automationId) as unknown as ActionRow[];
158	}
159	
160	function loadEdgeRows(database: DatabaseSync, automationId: string): EdgeRow[] {
161	    return database.prepare(`
162	        SELECT e.source_action_id, e.target_action_id
163	        FROM automation_action_edges e
164	        INNER JOIN automation_actions a ON a.id = e.source_action_id
165	            AND a.deleted_at IS NULL
166	        WHERE a.automation_id = ?
167	        ORDER BY e.source_action_id, e.target_action_id
168	    `).all(automationId) as unknown as EdgeRow[];
169	}
170	
171	function buildActionPayload(row: ActionRow): AutomationAction {
172	    switch (row.type) {
173	    case 'wait':
174	        return {
175	            id: row.id,
176	            type: 'wait',
177	            data: {
178	                wait_hours: requireValue(row.wait_hours, 'wait_hours', row)
179	            }
180	        };
181	    case 'send_email':
182	        return {
183	            id: row.id,
184	            type: 'send_email',
185	            data: {
186	                email_subject: requireValue(row.email_subject, 'email_subject', row),
187	                email_lexical: requireValue(row.email_lexical, 'email_lexical', row),
188	                email_sender_name: row.email_sender_name,
189	                email_sender_email: row.email_sender_email,
190	                email_sender_reply_to: row.email_sender_reply_to,
191	                email_design_setting_id: requireValue(row.email_design_setting_id, 'email_design_setting_id', row)
192	            }
193	        };
194	    }
195	}
196	
197	function requireValue<T>(value: T | null, field: string, row: ActionRow): T {
198	    if (value === null) {
199	        throw new errors.InternalServerError({
200	            message: tpl(messages.invalidAutomationActionRevision, {
201	                actionId: row.id,
202	                actionType: row.type,
203	                field
204	            })
205	        });
206	    }
207	
208	    return value;
209	}
210	
211	function buildEdgePayload(edge: EdgeRow): AutomationEdge {
212	    return {
213	        source_action_id: edge.source_action_id,
214	        target_action_id: edge.target_action_id
215	    };
216	}
217	
218	function buildPagination(total: number) {
219	    return {
220	        page: 1,
221	        pages: 1,
222	        limit: 'all' as const,
223	        total,
224	        prev: null,
225	        next: null
226	    };
227	}
228

